"""Semantic illustrations replacing every exact reuse in the expanded atlas.
Shared primitives and miniature components are intentional; no label/hash-based variants.
Executed by build_art.py after the original illustration family is defined.
"""
def mini(k,x,y,scale=.4):return group(A[k],f'translate({x} {y}) scale({scale})')
def ring(x,y,r,c='url(#gold)',w=3):return circle(x,y,r,'none',c,w)
def bars(x,y,n=4,c='#bde2d1'):
 return ''.join(rect(x+i*7,y,4,13+(i%3)*5,c,1) for i in range(n))
def node(x,y,c='url(#gold)',r=6):return circle(x,y,r,c,'#e7e5cc',1)
def hexagon(x,y,r=12,c='none',stroke='#b5d7c0'):
 pts=' '.join(f'{x+math.cos(i*math.pi/3)*r:.1f},{y+math.sin(i*math.pi/3)*r:.1f}' for i in range(6))
 return f'<polygon points="{pts}" fill="{c}" stroke="{stroke}" stroke-width="2"/>'
def lattice(x=24,y=28,nx=4,ny=3,size=10):
 return ''.join(hexagon(x+i*size*1.5,y+j*size*1.73+(i%2)*size*.865,size) for i in range(nx) for j in range(ny))
def tube_device(c='url(#teal)'):
 return rect(23,34,67,35,c,6,'#d4dccc')+ellipse(91,51,10,18,'url(#glass)','#dbe8d3')+line('M27 79H84M40 69V79M72 69V79','#b1c6b2',4)
def board_base():return rect(24,22,73,79,'url(#teal)',8,'#bfdbc4')
def pins():return ''.join(line(f'M{x} 18V29M{x} 88V101M18 {x}H29M88 {x}H101','#ccbd91',3) for x in [37,49,61,73,85])
def chip_base():return pins()+rect(29,29,59,59,'url(#coal)',7,'#b3c4ad')+rect(38,38,41,41,'#628c7b',5)
def sphere_world(c='url(#water)',land='#8fbb91'):
 return circle(60,60,39,c,'#d3e0cf',1.5)+path('M35 32L49 28L59 39L52 52L40 51L32 67L24 60M82 39L91 55L80 65L83 80L67 91L67 73L73 61L64 51Z',land)
def city_blocks(c='url(#teal)',n=4):
 out=''
 for i in range(n):
  x=16+i*23;h=[38,59,46,67][i%4];y=100-h
  out+=rect(x,y,19,h,c,3,'#b9cbbc')+''.join(rect(x+5,y+8+j*12,8,5,'#ede1a1',1) for j in range(max(1,(h-14)//12)))
 return out+line('M11 103H110','#d5c194',3)
def cell_body(c='url(#mint)'):
 return path('M24 40C32 17 65 18 85 34S106 75 87 94S37 103 23 82S14 60 24 40Z',c,'#d4e7ce',2)+ellipse(60,57,16,19,'url(#violet)','#e1d7e1',1.5)+circle(64,53,5,'#f1d7ac')
def helix(highlight=False):
 v=line('M34 17C101 44 20 77 85 103','#a7d6c3',5)+line('M85 17C20 44 101 77 34 103','#ccb2d5',5)
 for y,x1,x2 in [(25,47,73),(39,41,79),(53,51,69),(67,45,75),(81,42,78),(95,48,72)]:v+=line(f'M{x1} {y}H{x2}', '#f1ca86' if highlight and y in [53,67] else '#cbd6b9',3)
 return v
